import sys

def max_journey_length(s):
    n = len(s)
    dp = [0] * (n + 1)

    for i in range(1, n + 1):
        for j in range(1, i):
            if s[i - j:i] == s[i - 2 * j:i - j]:
                dp[i] = max(dp[i], dp[i - j] + 1)
        dp[i] = max(dp[i], 1)

    return max(dp)

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    s = input[1]
    print(max_journey_length(s))

if __name__ == "__main__":
    main()
